export const MESURER_STYLES = '.mesurer-solid-root{position:fixed;inset:0;z-index:2147483000;pointer-events:none;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#111827;font-size:12px;line-height:1.25;box-sizing:border-box}\n.mesurer-solid-root *{box-sizing:border-box}\n.msr-overlay{position:absolute;inset:0;user-select:none;pointer-events:none}\n.msr-overlay--crosshair{cursor:crosshair}\n.msr-hover-rect,.msr-drag-rect,.msr-measurement,.msr-box-model{position:absolute;pointer-events:none}\n.msr-hover-rect{outline:1px solid;outline-offset:-1px}\n.msr-drag-rect{border:1px solid}\n.msr-box-model--margin{background:rgba(245,158,11,.12);outline:1px solid rgba(245,158,11,.42)}\n.msr-box-model--padding{background:rgba(34,197,94,.10);outline:1px solid rgba(34,197,94,.35)}\n.msr-edge{position:absolute;display:block;pointer-events:none}\n.msr-edge--top,.msr-edge--bottom{left:0;width:100%;height:1px}\n.msr-edge--top{top:0}.msr-edge--bottom{bottom:0}\n.msr-edge--left,.msr-edge--right{top:0;height:100%;width:1px}\n.msr-edge--left{left:0}.msr-edge--right{right:0}\n.msr-measure-tag,.msr-option-tag,.msr-distance-tag{position:absolute;transform:translateX(-50%);z-index:20;border:0;border-radius:5px;background:rgba(17,24,39,.92);color:#fff;padding:2px 5px;font:500 10px/1.25 ui-monospace,SFMono-Regular,Menlo,monospace;white-space:nowrap;pointer-events:none;font-variant-numeric:tabular-nums}\n.msr-distance-tag{pointer-events:auto;cursor:pointer}\n.msr-distance-tag--v,.msr-option-tag{transform:translateY(-50%)}\n.msr-distance-line,.msr-option-line{position:absolute;display:block;background:#2563eb;pointer-events:none;z-index:12}\n.msr-distance-line--h,.msr-option-line--h{height:1px}.msr-distance-line--v,.msr-option-line--v{width:1px}\n.msr-guide-hitbox{position:absolute;z-index:10;cursor:default}\n.msr-guide-line{position:absolute;display:block;pointer-events:none}\n.msr-guide-preview{position:absolute;pointer-events:none;border:0 dashed transparent;z-index:9}\n.msr-guide-preview[style*="height: 100%"]{border-left-width:1px;border-left-style:dashed}\n.msr-guide-preview[style*="width: 100%"]{border-top-width:1px;border-top-style:dashed}\n.msr-rulers{position:absolute;inset:0;z-index:30;pointer-events:none;color:#475569;font:9px/1 ui-monospace,SFMono-Regular,Menlo,monospace}\n.msr-ruler{position:absolute;background:rgba(248,250,252,.94);border-color:rgba(15,23,42,.12);pointer-events:auto;overflow:hidden;cursor:crosshair;backdrop-filter:blur(8px)}\n.msr-ruler--top{left:22px;right:0;top:0;height:22px;border-bottom:1px solid rgba(15,23,42,.12)}\n.msr-ruler--left{left:0;top:22px;bottom:0;width:22px;border-right:1px solid rgba(15,23,42,.12)}\n.msr-ruler-corner{position:absolute;left:0;top:0;width:22px;height:22px;background:rgba(248,250,252,.96);border-right:1px solid rgba(15,23,42,.12);border-bottom:1px solid rgba(15,23,42,.12);pointer-events:auto}\n.msr-ruler-tick{position:absolute;display:block;background:rgba(71,85,105,.45)}\n.msr-ruler--top .msr-ruler-tick{bottom:0;width:1px;height:5px}.msr-ruler--top .msr-ruler-tick--major{height:9px}\n.msr-ruler--left .msr-ruler-tick{right:0;height:1px;width:5px}.msr-ruler--left .msr-ruler-tick--major{width:9px}\n.msr-ruler-tick em{position:absolute;font:inherit;font-style:normal;color:#64748b;user-select:none}\n.msr-ruler--top .msr-ruler-tick em{left:2px;top:2px}.msr-ruler--left .msr-ruler-tick em{top:2px;left:2px;writing-mode:vertical-rl}\n.msr-toolbar-wrap{position:absolute;z-index:100;pointer-events:none}\n.msr-toolbar-surface{height:40px;display:flex;align-items:center;gap:2px;padding:4px;border:1px solid rgba(15,23,42,.1);border-radius:12px;background:rgba(255,255,255,.96);box-shadow:0 8px 30px rgba(15,23,42,.14),0 1px 4px rgba(15,23,42,.1);pointer-events:auto;backdrop-filter:blur(14px)}\n.msr-tool,.msr-grip{appearance:none;border:0;background:transparent;color:#111827;width:32px;height:32px;border-radius:8px;display:grid;place-items:center;font:600 12px/1 system-ui;cursor:pointer;user-select:none}\n.msr-tool:hover,.msr-grip:hover{background:rgba(15,23,42,.055)}\n.msr-tool.is-active{background:#0d99ff;color:#fff}\n.msr-grip{width:18px;color:#94a3b8;cursor:grab;letter-spacing:-3px;padding:0}.msr-grip:active{cursor:grabbing}\n.msr-toolbar-divider{width:1px;height:20px;background:rgba(15,23,42,.1);margin:0 2px}\n.msr-settings{position:absolute;left:0;top:48px;width:360px;pointer-events:auto;background:#fff;border:1px solid rgba(15,23,42,.1);border-radius:14px;box-shadow:0 18px 50px rgba(15,23,42,.18);overflow:hidden;color:#0f172a}\n.msr-settings header,.msr-color-card header{display:flex;align-items:center;justify-content:space-between;padding:12px 14px;border-bottom:1px solid #e2e8f0}\n.msr-settings header button,.msr-color-card header button{border:0;background:transparent;font-size:18px;cursor:pointer;color:#64748b}\n.msr-settings nav{display:flex;overflow-x:auto;gap:2px;padding:7px;border-bottom:1px solid #e2e8f0;background:#f8fafc}\n.msr-settings nav button{border:0;background:transparent;padding:6px 8px;border-radius:7px;font-size:11px;color:#64748b;cursor:pointer;white-space:nowrap}\n.msr-settings nav button.is-active{background:#fff;color:#0f172a;box-shadow:0 1px 3px rgba(15,23,42,.12)}\n.msr-settings section{padding:12px 14px;min-height:145px;max-height:330px;overflow:auto}\n.msr-setting-row{display:flex;align-items:center;justify-content:space-between;gap:14px;min-height:34px;border-bottom:1px solid #f1f5f9}\n.msr-setting-row input[type="range"]{width:140px}.msr-setting-row select{max-width:150px}\n.msr-setting-stack{display:flex;flex-direction:column;gap:9px}\n.msr-help{margin:7px 0;color:#64748b;font-size:10px;line-height:1.4}\n.msr-settings footer{display:flex;justify-content:space-between;padding:10px 14px;background:#f8fafc;border-top:1px solid #e2e8f0}\n.msr-settings footer button{border:1px solid #cbd5e1;background:#fff;border-radius:7px;padding:6px 9px;font-size:11px;cursor:pointer}.msr-settings footer button.is-danger{color:#b91c1c}\n.msr-color-card{position:absolute;left:20px;top:72px;z-index:110;width:300px;pointer-events:auto;background:#fff;border:1px solid rgba(15,23,42,.1);border-radius:13px;box-shadow:0 15px 45px rgba(15,23,42,.18);overflow:hidden}\n.msr-color-card p{padding:12px 14px;margin:0;color:#64748b}\n.msr-color-swatch{height:54px;margin:12px;border-radius:9px;border:1px solid rgba(15,23,42,.1)}\n.msr-color-value{width:calc(100% - 24px);margin:0 12px 7px;display:grid;grid-template-columns:48px 1fr;gap:8px;align-items:center;text-align:left;border:1px solid #e2e8f0;background:#fff;border-radius:7px;padding:7px;cursor:pointer}.msr-color-value span{font-size:9px;color:#64748b}.msr-color-value code{overflow:hidden;text-overflow:ellipsis;font-size:10px;color:#0f172a}\n@media (prefers-color-scheme:dark){.msr-toolbar-surface,.msr-settings,.msr-color-card{background:rgba(15,23,42,.96);color:#f8fafc;border-color:rgba(255,255,255,.12)}.msr-tool{color:#f8fafc}.msr-tool:hover,.msr-grip:hover{background:rgba(255,255,255,.08)}.msr-toolbar-divider{background:rgba(255,255,255,.12)}.msr-settings nav,.msr-settings footer{background:#111827;border-color:#334155}.msr-settings nav button.is-active{background:#1e293b;color:#fff}.msr-settings section,.msr-setting-row{border-color:#1e293b}.msr-color-value{background:#111827;border-color:#334155}.msr-color-value code{color:#f8fafc}.msr-ruler,.msr-ruler-corner{background:rgba(15,23,42,.92);color:#cbd5e1;border-color:#334155}}\n';
